#include <vector>
#include <iostream>

int main() {
    std::vector<bool> c = {true, false, true};

    // Access returns the proxy object 'reference'
    auto ref = c[1]; 

    // Use the proxy's specialized member function
    c.front().flip(); // Negates the first element

    // Assignment via proxy (c[2] = c[1])
    c.at(2) = ref;

    // Output: 0 0 0 (since c[0] flipped to false)
    for (bool b : c) {
        std::cout << b << " ";
    }
}
